 */
public enum CoreErrorFfi: Swift.Error {

    
    
    case InvalidInput
    case DecryptFailed
    case UnsupportedFormat
    case KdfFailed
    /**
     * A core error category added after this binding was built (forward-compat catch-all).
     */
    case Unknown
}


#if swift(>=5.8)
@_documentation(visibility: private)
