public struct FfiConverterTypeCoreErrorFfi: FfiConverterRustBuffer {
    typealias SwiftType = CoreErrorFfi

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CoreErrorFfi {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidInput
        case 2: return .DecryptFailed
        case 3: return .UnsupportedFormat
        case 4: return .KdfFailed
        case 5: return .Unknown

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CoreErrorFfi, into buf: inout [UInt8]) {
        switch value {

        

        
        
