public struct FfiConverterTypeKdfKindFfi: FfiConverterRustBuffer {
    typealias SwiftType = KdfKindFfi

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> KdfKindFfi {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .pbkdf2HmacSha256(iterations: try FfiConverterUInt32.read(from: &buf)
